# ═══════════════════════════════════════════════════════════════
# SERVIDOR DE RELAY HTTP
# ═══════════════════════════════════════════════════════════════

def _local_ip() -> str:
    """Devuelve la IP local del ordenador en la red doméstica."""
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except Exception:
        return "127.0.0.1"


RELAY_HEADERS = {
    "User-Agent": "Mozilla/5.0 (Linux; Android 11; Redmi Note) AppleWebKit/537.36 VLC/3.0",
    "Accept": "*/*",
    "Connection": "keep-alive",
}


class RelayHandler(BaseHTTPRequestHandler):
    """
    Gestiona las peticiones HTTP del relay:
      GET /          → página de estado HTML
      GET /stream    → proxea el stream IPTV activo (HLS o TS)
      GET /proxy?url → proxea cualquier URL (segmentos HLS reescritos)
    """
    current_url: str = None
    active_clients: int = 0
    _lock = threading.Lock()

    # ── Enrutado ──────────────────────────────────────────────────
    def do_GET(self):
        if self.path in ("/", "/status"):
            self._serve_status()
        elif self.path == "/stream":
            url = RelayHandler.current_url
            if url:
                self._proxy(url)
            else:
                self.send_error(503, "Sin canal activo — selecciona un canal en SLOCast")
        elif self.path.startswith("/proxy?"):
            raw = self.path[len("/proxy?"):]
            params = urllib.parse.parse_qs(raw)
            target = urllib.parse.unquote(params.get("url", [""])[0])
            if target:
                self._proxy(target)
            else:
                self.send_error(400, "Parámetro 'url' requerido")
        else:
            self.send_error(404, "Ruta no encontrada")

    # ── Página de estado ─────────────────────────────────────────
    def _serve_status(self):
        ip   = _local_ip()
        port = self.server.server_port
        ch   = RelayHandler.current_url or "— ninguno —"
        n    = RelayHandler.active_clients
        html = f"""<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8">
<meta http-equiv="refresh" content="3">
<title>SLOCast Relay</title>
<style>
  body{{background:#0f0f0f;color:#e0e0e0;font-family:sans-serif;
        text-align:center;padding:40px;margin:0}}
  h1{{color:#FFB300;margin-bottom:4px}} h2{{color:#aaa;font-size:14px;margin-top:0}}
  .url{{background:#071407;color:#2ECC71;font-family:monospace;padding:12px 20px;
        border-radius:6px;font-size:16px;display:inline-block;margin:16px 0}}
  .badge{{display:inline-block;padding:4px 12px;border-radius:12px;font-size:13px}}
  .green{{background:#1a4a1a;color:#2ECC71}} .red{{background:#4a1a1a;color:#E74C3C}}
  a{{color:#FFB300}} p{{color:#aaa;font-size:13px}}
</style></head><body>
<h1>👑 SLOCast Relay</h1>
<h2>Servidor de streaming local</h2>
<span class="badge {'green' if RelayHandler.current_url else 'red'}">
  {'🟢 Canal activo' if RelayHandler.current_url else '🔴 Sin canal'}</span>
&nbsp;
<span class="badge {'green' if n > 0 else ''}">📱 {n} cliente(s) conectado(s)</span>
<br><br>
<div class="url">http://{ip}:{port}/stream</div>
<p>Pega esta URL en VLC, MX Player o el navegador de tu Xiaomi TV / Smart TV.</p>
<p><a href="/stream">▶ Reproducir aquí mismo</a></p>
<p style="color:#555;font-size:11px">Canal: {ch[:80]}</p>
</body></html>"""
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.end_headers()
        self.wfile.write(html.encode())

    # ── Proxy genérico ────────────────────────────────────────────
    def _proxy(self, url: str):
        with RelayHandler._lock:
            RelayHandler.active_clients += 1
        try:
            req = urllib.request.Request(url, headers=RELAY_HEADERS)
            with urllib.request.urlopen(req, timeout=20) as resp:
                ct    = resp.headers.get("Content-Type", "")
                data  = resp.read(65536)  # leer inicio para detectar HLS

                is_hls = (
                    "mpegurl" in ct.lower()
                    or url.split("?")[0].endswith(".m3u8")
                    or data.lstrip().startswith(b"#EXTM3U")
                )

                if is_hls:
                    # Leer el resto del manifiesto
                    data += resp.read()
                    rewritten = self._rewrite_hls(data.decode("utf-8", "ignore"), url)
                    payload   = rewritten.encode("utf-8")
                    self.send_response(200)
                    self.send_header("Content-Type", "application/vnd.apple.mpegurl")
                    self.send_header("Content-Length", str(len(payload)))
                    self.send_header("Cache-Control", "no-cache, no-store")
                    self.send_header("Access-Control-Allow-Origin", "*")
                    self.end_headers()
                    self.wfile.write(payload)
                else:
                    # Stream binario (TS, MP4…) → pipe continuo
                    self.send_response(200)
                    self.send_header("Content-Type", ct or "video/mp2t")
                    self.send_header("Cache-Control", "no-cache, no-store")
                    self.send_header("Access-Control-Allow-Origin", "*")
                    self.end_headers()
                    self.wfile.write(data)
                    while True:
                        chunk = resp.read(65536)
                        if not chunk:
                            break
                        self.wfile.write(chunk)
        except (BrokenPipeError, ConnectionResetError):
            pass  # Cliente desconectado — completamente normal
        except Exception as exc:
            try:
                self.send_error(502, str(exc))
            except Exception:
                pass
        finally:
            with RelayHandler._lock:
                RelayHandler.active_clients -= 1

    # ── Reescritura de playlist HLS ───────────────────────────────
    def _rewrite_hls(self, content: str, base_url: str) -> str:
        """
        Reescribe las URLs de segmentos/variantes de un manifiesto HLS
        para que pasen por el relay (soporte de TVs que no soportan
        cookies/headers de autenticación del proveedor IPTV).
        """
        ip   = _local_ip()
        port = self.server.server_port
        base = base_url.rsplit("/", 1)[0] + "/"
        lines = []
        for line in content.splitlines():
            s = line.strip()
            if s and not s.startswith("#"):
                if s.startswith("http://") or s.startswith("https://"):
                    full = s
                else:
                    full = urllib.parse.urljoin(base, s)
                enc  = urllib.parse.quote(full, safe="")
                line = f"http://{ip}:{port}/proxy?url={enc}"
            lines.append(line)
        return "\n".join(lines)

    def log_message(self, *_):
        pass  # Silenciar logs del servidor HTTP en consola


class StreamRelayServer:
    """Gestiona el ThreadingHTTPServer en un hilo daemon."""

    PORT = 8765

    def __init__(self):
        self._server: ThreadingHTTPServer | None = None
        self.running = False

    def start(self) -> bool:
        if self.running:
            return True
        try:
            self._server = ThreadingHTTPServer(("0.0.0.0", self.PORT), RelayHandler)
            t = threading.Thread(target=self._server.serve_forever, daemon=True)
            t.start()
            self.running = True
            return True
        except OSError as e:
            print(f"[Relay] No se pudo iniciar en puerto {self.PORT}: {e}")
            return False

    def stop(self):
        if self._server:
            self._server.shutdown()
            self.running = False

    def set_stream(self, url: str):
        RelayHandler.current_url = url

    def clear_stream(self):
        RelayHandler.current_url = None

    @property
    def stream_url(self) -> str:
        return f"http://{_local_ip()}:{self.PORT}/stream"

    @property
    def status_url(self) -> str:
        return f"http://{_local_ip()}:{self.PORT}/"


