class M3ULoader(QThread):
    loaded   = pyqtSignal(list)
    failed   = pyqtSignal(str)
    progress = pyqtSignal(str)

    def __init__(self, source: str):
        super().__init__()
        self.source = source

    def run(self):
        try:
            if self.source.startswith(("http://", "https://")):
                self.progress.emit("Descargando lista...")
                req = urllib.request.Request(
                    self.source,
                    headers={"User-Agent": "Mozilla/5.0 VLC/3.0"}
                )
                with urllib.request.urlopen(req, timeout=25) as resp:
                    content = resp.read().decode("utf-8", "ignore")
            else:
                self.progress.emit("Leyendo archivo...")
                content = Path(self.source).read_text(encoding="utf-8", errors="ignore")

            self.progress.emit("Procesando canales...")
            self.loaded.emit(self._parse(content))
        except Exception as e:
            self.failed.emit(str(e))

    @staticmethod
    def _parse(content: str) -> list:
        channels, cur_name, cur_group = [], "Canal", ""
        for line in content.splitlines():
            line = line.strip()
            if line.startswith("#EXTINF:"):
                parts = line.split(",", 1)
                cur_name = parts[1].strip() if len(parts) > 1 else "Canal"
                cur_group = ""
                if 'group-title="' in line:
                    try:
                        cur_group = line.split('group-title="')[1].split('"')[0]
                    except IndexError:
                        pass
            elif line and not line.startswith("#"):
                channels.append({"name": cur_name, "url": line, "group": cur_group})
                cur_name, cur_group = "Canal", ""
        return channels


